<?php
echo '<div class="page-head"><div><h1>Stock Exceptions</h1><p>Trace negative balances, assign an owner and record the posted correction.</p></div></div>';
$status=($_GET['exception_status']??'Open')==='Resolved'?'Resolved':'Open';echo '<div class="tabs"><a class="tab" href="?page=stock_exceptions">Open</a><a class="tab" href="?page=stock_exceptions&exception_status=Resolved">Resolved History</a></div>';
$owners=operational_users('negative_resolve');$offset=max(0,(int)($_GET['offset']??0));$q=db()->prepare('SELECT x.*,p.name,p.master_sku,u.name opened_name,o.name owner_name,r.name resolved_name FROM stock_exceptions x JOIN products p ON p.id=x.product_id LEFT JOIN users u ON u.id=x.opened_by LEFT JOIN users o ON o.id=x.assigned_to LEFT JOIN users r ON r.id=x.resolved_by WHERE x.status=? ORDER BY x.id DESC LIMIT 51 OFFSET '.$offset);$q->execute([$status]);$rows=$q->fetchAll();$more=count($rows)>50;$rows=array_slice($rows,0,50);
echo '<div class="card table-wrap"><table class="table"><tr><th>Date / Reference</th><th>Product</th><th>Platform</th><th>Before → After</th><th>Current</th><th>Processed By / Owner</th><th>Resolution</th></tr>';foreach($rows as $r){echo '<tr><td>'.e($r['txn_date']).'<br>'.e($r['reference_no']).'<br>'.e($r['created_at']).'</td><td>'.e($r['name']).'<br>'.e($r['master_sku']).'</td><td>'.e($r['platform']).'</td><td>'.$r['before_qty'].' → '.$r['after_qty'].'</td><td>'.platform_qty($r['platform'],$r['product_id']).'</td><td>'.e($r['opened_name']).'<br>Owner: '.e($r['owner_name']?:'Unassigned').'</td><td>';if($status==='Resolved')echo e($r['reason']).'<br>Correction: '.e($r['correction_reference']).'<br>'.e($r['resolved_name']).' · '.e($r['resolved_at']);else{
 if(current_user()['role']==='Admin'){echo '<form method="post" action="actions.php" class="stack"><input type="hidden" name="action" value="negative_assign"><input type="hidden" name="exception_id" value="'.$r['id'].'"><input type="hidden" name="return" value="stock_exceptions"><select name="owner_id" required><option value="">Assign owner</option>';foreach($owners as $o)echo '<option value="'.$o['id'].'">'.e($o['name']).'</option>';echo '</select><input name="reason" placeholder="Assignment note" required><button class="btn secondary sm">Assign</button></form>';}
 if(current_user()['role']==='Admin'||(int)$r['assigned_to']===current_user()['id'])echo '<form method="post" action="actions.php" class="stack" data-confirm="Resolve this exception using the posted correction reference?"><input type="hidden" name="action" value="negative_resolve"><input type="hidden" name="exception_id" value="'.$r['id'].'"><input type="hidden" name="return" value="stock_exceptions"><input name="correction_reference" placeholder="Posted correction reference" required><textarea name="reason" placeholder="Cause and correction" required></textarea><button class="btn primary sm">Resolve Exception</button></form>';else echo e($r['reason']);}echo '</td></tr>';}
if(!$rows)echo '<tr><td colspan="7">No '.$status.' exceptions.</td></tr>';echo '</table>';if($offset)echo '<a class="btn ghost" href="?page=stock_exceptions&exception_status='.$status.'&offset='.max(0,$offset-50).'">Previous</a>';if($more)echo '<a class="btn ghost" href="?page=stock_exceptions&exception_status='.$status.'&offset='.($offset+50).'">Next</a>';echo '</div>';
